import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [resorts, setResorts] = useState([]);
  const [filteredResorts, setFilteredResorts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchResorts() {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/ski-resorts`);
        console.log('API Response:', response.data);
        setResorts(response.data); // Adjust based on the actual structure
        setFilteredResorts(response.data); // Adjust if response.data is not directly an array
      } catch (error) {
        setError('Error fetching resorts');
      }
    }

    fetchResorts();
  }, []);

  // Function to handle search
  const handleSearch = () => {
    if (Array.isArray(resorts)) {
      setFilteredResorts(
        resorts.filter(resort =>
          resort.name.toLowerCase().includes(searchTerm.toLowerCase())
        )
      );
    }
  };

  return (
    <div>
      <h1>Ski Resorts</h1>
      <input
        type="text"
        placeholder="Search resorts..."
        value={searchTerm}
        onChange={e => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      {error && <p>{error}</p>}
      <ul>
        {Array.isArray(filteredResorts) && filteredResorts.map((resort, index) => (
          <li key={index}>{resort.name}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
